<?php declare(strict_types=1);use FastWebsite\Core\View;$authorName=static fn(array$a):string=>$a['staff_id']?trim(implode(' ',array_filter([$a['honorific_title'],$a['first_name'],$a['middle_name'],$a['last_name']]))):(string)$a['external_author_name'];?>
<section class="admin-page-heading"><div><p class="eyebrow"><?=View::escape($publication['type_name'])?></p><h1><?=View::escape($publication['title'])?></h1><span class="status-badge status-<?=View::escape($publication['status'])?>"><?=View::escape(ucfirst(str_replace('_',' ',$publication['status'])))?></span></div><div class="heading-actions"><a class="button button-secondary" href="<?=View::escape($baseUrl)?>admin/research/publications">All publications</a><?php if($canEdit):?><a class="button <?=$canQuickPublish?'button-secondary':'button-primary'?>" href="<?=View::escape($baseUrl)?>admin/research/publications/<?=(int)$publication['id']?>/edit">Edit</a><?php endif;?><?php if($canQuickPublish):?><form method="post" action="<?=View::escape($baseUrl)?>admin/research/publications/<?=(int)$publication['id']?>/workflow"><input type="hidden" name="_token" value="<?=View::escape($csrfToken)?>"><input type="hidden" name="action" value="publish_now"><button class="button button-primary" type="submit">Publish now</button></form><?php endif;?></div></section><?php if(is_string($success)&&$success!==''):?><div class="success-alert"><?=View::escape($success)?></div><?php endif;?><?php if($needsAuthor):?><div class="form-alert publish-guidance"><strong>Ready to publish?</strong> Add at least one author below; the Publish now button will then appear.</div><?php endif;?>
<div class="record-grid"><div class="record-main"><?php if($publication['abstract']):?><section class="admin-panel record-section"><h2>Abstract</h2><div class="prose"><?=nl2br(View::escape($publication['abstract']))?></div></section><?php endif;?><?php if($publication['citation_text']):?><section class="admin-panel record-section"><h2>Preferred citation</h2><div class="prose"><?=nl2br(View::escape($publication['citation_text']))?></div></section><?php endif;?>
<section class="admin-panel" id="authors"><div class="panel-heading"><h2>Authors</h2></div><?php if($authors===[]):?><p class="admin-empty compact">No authors added yet.</p><?php else:?><div class="table-scroll"><table class="admin-table"><thead><tr><th>Order</th><th>Author</th><th>Affiliation</th><th></th></tr></thead><tbody><?php foreach($authors as$a):?><tr><td><?=(int)$a['author_order']?></td><th><?=View::escape($authorName($a))?><small><?=($a['is_corresponding']?'Corresponding · ':'').($a['staff_id']?'FAST staff':'External author')?></small></th><td><?=View::escape($a['external_affiliation']??'FAST')?></td><td><?php if($canManageAuthors):?><form method="post" action="<?=View::escape($baseUrl)?>admin/research/publications/<?=(int)$publication['id']?>/authors/<?=(int)$a['id']?>/remove" onsubmit="return confirm('Remove this author?')"><input type="hidden" name="_token" value="<?=View::escape($csrfToken)?>"><button class="button button-secondary button-compact" type="submit">Remove</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?><?php if($canManageAuthors):?><form class="content-form member-form" method="post" action="<?=View::escape($baseUrl)?>admin/research/publications/<?=(int)$publication['id']?>/authors"><input type="hidden" name="_token" value="<?=View::escape($csrfToken)?>"><p class="form-help">Choose one FAST staff author or enter one external author name, not both.</p><div class="form-grid"><div class="form-field"><label for="staff_id">FAST staff author</label><select id="staff_id" name="staff_id"><option value="">External author</option><?php foreach($staffOptions as$s):?><option value="<?=(int)$s['id']?>"><?=View::escape(trim(implode(' ',array_filter([$s['honorific_title'],$s['first_name'],$s['middle_name'],$s['last_name']]))))?></option><?php endforeach;?></select></div><div class="form-field"><label for="external_author_name">External author name</label><input id="external_author_name" name="external_author_name" maxlength="200"></div><div class="form-field"><label for="external_affiliation">External affiliation</label><input id="external_affiliation" name="external_affiliation" maxlength="255"></div><div class="form-field"><label for="external_orcid">External ORCID</label><input id="external_orcid" name="external_orcid" maxlength="50" placeholder="0000-0000-0000-0000"></div><div class="form-field"><label for="author_order">Author order</label><input id="author_order" name="author_order" type="number" min="1" max="65535" value="<?=count($authors)+1?>" required></div><div class="form-field checkbox-field"><label><input name="is_corresponding" type="checkbox" value="1"> Corresponding author</label></div></div><button class="button button-primary" type="submit">Add author</button></form><?php endif;?></section></div>
<aside class="record-sidebar"><section class="admin-panel"><h2>Bibliographic details</h2><dl class="detail-list"><div><dt>Type</dt><dd><?=View::escape($publication['type_name'])?></dd></div><div><dt>Year</dt><dd><?=View::escape((string)($publication['publication_year']??'Not set'))?></dd></div><?php if($publication['journal_name']):?><div><dt>Journal/source</dt><dd><?=View::escape($publication['journal_name'])?></dd></div><?php endif;?><?php if($publication['doi']):?><div><dt>DOI</dt><dd><a href="https://doi.org/<?=View::escape($publication['doi'])?>"><?=View::escape($publication['doi'])?></a></dd></div><?php endif;?><div><dt>Access</dt><dd><?=View::escape(ucwords(str_replace('_',' ',$publication['access_type'])))?></dd></div><div><dt>Public URL</dt><dd>/research/publications/<?=View::escape($publication['slug'])?></dd></div></dl></section><?php if($projects!==[]||$units!==[]):?><section class="admin-panel"><h2>Research links</h2><?php foreach($projects as$p):?><p><strong>Project</strong><br><?=View::escape($p['title'])?></p><?php endforeach;?><?php foreach($units as$u):?><p><strong>Research unit</strong><br><?=View::escape($u['name'])?></p><?php endforeach;?></section><?php endif;?><?php if($actions!==[]):?><section class="admin-panel"><h2>Workflow action</h2><form class="workflow-form" method="post" action="<?=View::escape($baseUrl)?>admin/research/publications/<?=(int)$publication['id']?>/workflow"><input type="hidden" name="_token" value="<?=View::escape($csrfToken)?>"><div class="form-field"><label for="publication-comment">Comment</label><textarea id="publication-comment" name="comment" rows="3"></textarea></div><div class="workflow-actions"><?php foreach($actions as$a):?><button class="button <?=$a['action']==='published'?'button-primary':'button-secondary'?>" type="submit" name="action" value="<?=View::escape($a['action'])?>"><?=View::escape($a['label'])?></button><?php endforeach;?></div></form></section><?php endif;?><section class="admin-panel"><h2>Workflow history</h2><?php if($history===[]):?><p class="admin-empty compact">No actions yet.</p><?php else:?><ol class="history-list"><?php foreach($history as$entry):?><li><strong><?=View::escape(ucfirst(str_replace('_',' ',$entry['action'])))?></strong><span><?=View::escape($entry['actor_name']??'Former user')?></span></li><?php endforeach;?></ol><?php endif;?></section></aside></div>
